#!/usr/bin/env node
// SessionStart for the plugin: prints the always-on rule, which a plugin cannot write to CLAUDE.md.
// The text comes from rule.txt next to this file, generated by scripts/build-plugin.js from locales/en/rule.md.
// Anything missing or unreadable prints nothing and exits 0, so the session is never blocked.
const fs = require('fs'), path = require('path');
let text = '';
try { text = fs.readFileSync(path.join(__dirname, 'rule.txt'), 'utf8'); } catch { /* missing file: no rule */ }
text = text.replace(/^﻿/, '').replace(/<!--[\s\S]*?-->/g, '').replace(/\r\n/g, '\n').trim();
// No process.exit: it could cut the output before it is flushed. The exit code is 0.
if (text) process.stdout.write(text + '\n');
